import json,glob,os,sys
from datetime import datetime
W=sys.argv[1]
rows=[]
for f in glob.glob(W+'/agent-*.jsonl'):
    meta=json.load(open(f.replace('.jsonl','.meta.json')))
    seen={}; order=[]; tss=[]
    for line in open(f,errors='replace'):
        try:r=json.loads(line)
        except: continue
        t=r.get('timestamp')
        if t: tss.append(t)
        m=r.get('message') if isinstance(r.get('message'),dict) else None
        if not m or 'usage' not in m: continue
        mid=m.get('id')
        if mid not in seen: order.append(mid)
        seen[mid]=m['usage']
    w=sum(u.get('input_tokens',0)+u.get('cache_creation_input_tokens',0) for u in seen.values())
    fu=seen[order[0]]; fc=fu.get('input_tokens',0)+fu.get('cache_creation_input_tokens',0)
    t0=min(tss); t1=max(tss)
    d0=datetime.fromisoformat(t0.replace('Z','+00:00')); d1=datetime.fromisoformat(t1.replace('Z','+00:00'))
    rows.append((t0,meta['description'],w,fc,len(seen),(d1-d0).total_seconds()/60,d0.strftime('%H:%M'),d1.strftime('%H:%M'),os.path.basename(f)[:23]))
rows.sort()
for r in rows: print(f"{r[1]:12} {r[2]/1e3:6.0f}K first {r[3]/1e3:4.0f}K turns {r[4]:4} {r[5]:6.1f} min {r[6]}-{r[7]} {r[8]}")

