import json,glob,os,sys,re
W=sys.argv[1]; pat=re.compile(sys.argv[2]); only=sys.argv[3] if len(sys.argv)>3 else None; n=int(sys.argv[4]) if len(sys.argv)>4 else 220
for f in sorted(glob.glob(W+'/agent-*.jsonl')):
    lab=json.load(open(f.replace('.jsonl','.meta.json')))['description']
    aid=os.path.basename(f)[6:13]
    if only and lab!=only and not os.path.basename(f).startswith('agent-'+only): continue
    uses={}; res={}
    for line in open(f,errors='replace'):
        try:r=json.loads(line)
        except: continue
        m=r.get('message')
        if not isinstance(m,dict): continue
        c=m.get('content')
        if not isinstance(c,list): continue
        for b in c:
            if b.get('type')=='tool_use':
                inp=b['input']; cmd=inp.get('command') or inp.get('file_path') or json.dumps(inp)[:200]
                uses[b['id']]=(r.get('timestamp','')[11:19],b['name'],cmd)
            if b.get('type')=='tool_result':
                cc=b.get('content'); 
                if isinstance(cc,list): cc=' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                res[b['tool_use_id']]=(b.get('is_error'),str(cc)[:n].replace('\n',' | '))
    for k,(t,name,cmd) in uses.items():
        if pat.search(name+' '+cmd):
            e=res.get(k,(None,''))
            print(f"{lab:10} {aid} {t} {name} err={e[0]} :: {cmd[:n]!r}\n      -> {e[1]}")
EOF
