import json,glob,os,sys,re
W=sys.argv[1]
for f in sorted(glob.glob(W+'/agent-*.jsonl')):
    lab=json.load(open(f.replace('.jsonl','.meta.json')))['description']
    if not lab.startswith('rung:'): continue
    edits=[]; runs=[]; res={}; uses={}
    for line in open(f,errors='replace'):
        r=json.loads(line); m=r.get('message')
        if not isinstance(m,dict): continue
        c=m.get('content')
        if not isinstance(c,list): continue
        for b in c:
            if b.get('type')=='tool_use':
                t=r['timestamp'][11:19]; inp=b['input']
                if b['name'] in ('Edit','Write','MultiEdit'):
                    p=inp.get('file_path','')
                    if re.search(r'(src/com/sun|Library/|LibraryBuiltin/)',p) and not re.search(r'/tests?/|compiler_tests|library_tests',p):
                        edits.append((t,b['name'],p.split('fortress-')[-1][:90]))
                if b['name']=='Bash':
                    cmd=inp.get('command','')
                    if re.search(r'(harness-one|junit\.sh)',cmd):
                        uses[b['id']]=(t,cmd)
                    # sed -i / python edits of source
                    if re.search(r"(sed -i|perl -pi|python3 - <<)",cmd) and re.search(r'(src/com/sun|Library/|LibraryBuiltin)',cmd):
                        edits.append((t,'Bash-edit',cmd[:90].replace('\n',' ')))
            if b.get('type')=='tool_result' and b['tool_use_id'] in uses:
                cc=b.get('content'); cc=cc if isinstance(cc,str) else ' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                mm=re.findall(r'(Tests run: \d+,\s+Failures: \d+|OK \(\d+ tests?\)|Saw expected failure)',cc)
                runs.append((uses[b['tool_use_id']][0], mm[-1] if mm else cc[-80:].replace('\n',' ')))
    print('==',lab, os.path.basename(f)[6:13])
    print(' first source edits:', edits[:3])
    print(' harness runs:', runs[:6])
EOF
